css:
:root {
  --fan-border: #01524F;

  /* Paleta más sobria, conservando el tono del TIRC_ID. */
  --fan-fill-light: #E2ECE8;
  --fan-fill-middle: #D0DFD9;
  --fan-fill-base: #BECEC7;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;
  border: none;

  background: transparent !important;
  pointer-events: none;
}

.fan-widget,
.fan-widget * {
  box-sizing: border-box;
}

.fan-widget {
  position: relative;
  width: 100%;
  height: 100%;
  margin: 0;
  padding: 0;
  overflow: hidden;

  background: transparent;
  pointer-events: none;
  user-select: none;
  opacity: var(--w-opacity, 1);
}

.fan-button {
  position: absolute;
  inset: 0;

  display: block;
  width: 100%;
  height: 100%;
  min-width: 0;
  min-height: 0;
  margin: 0;
  padding: 0;

  appearance: none;
  border: none;
  background: transparent;

  pointer-events: none;
  cursor: pointer;
  user-select: none;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

.fan-svg {
  display: block;
  width: 100%;
  height: 100%;
  overflow: hidden;

  background: transparent;
  shape-rendering: geometricPrecision;
  pointer-events: none;
}

/* Posición fija, sin animación de giro. */
.fan-drawing {
  transform-box: view-box;
  transform-origin: 50% 50%;
  transform: scale(1);
  pointer-events: none;
}

.fan-fill-light {
  stop-color: var(--fan-fill-light);
}

.fan-fill-middle {
  stop-color: var(--fan-fill-middle);
}

.fan-fill-base {
  stop-color: var(--fan-fill-base);
}

.fan-fill-light,
.fan-fill-middle,
.fan-fill-base {
  transition: stop-color 100ms ease;
}

.fan-blade-body {
  fill: url("#fan-surface");
  stroke: var(--fan-border);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.fan-hub {
  fill: url("#fan-hub-surface");
  stroke: var(--fan-border);
  stroke-width: 3;
}

.fan-center {
  fill: var(--fan-border);
  stroke: none;
  opacity: 0.85;
}

.fan-highlight,
.fan-hub-highlight {
  fill: none;
  stroke: #FFFFFF;
  stroke-width: 1.2;
  stroke-linecap: round;
  opacity: 0.28;

  transition: opacity 100ms ease;
}

.fan-hub-highlight {
  opacity: 0.22;
}

.fan-pressed-shadow {
  fill: none;
  stroke: var(--fan-border);
  stroke-width: 3;
  stroke-linecap: round;
  opacity: 0;

  transition: opacity 100ms ease;
}

/* Interacción interna limitada a las palas y su unión central. */
.fan-hit-area {
  fill: transparent;
  stroke: transparent;
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;

  pointer-events: all;
  cursor: pointer;
}

@media (hover: hover) {
  .fan-button:hover {
    --fan-fill-light: #E7EFEB;
    --fan-fill-middle: #D5E3DD;
    --fan-fill-base: #C3D3CC;
  }

  .fan-button:hover .fan-highlight {
    opacity: 0.35;
  }
}

/* Pulsación discreta, centrada y sin desplazamiento. */
.fan-button:active {
  --fan-fill-light: #D5E1DB;
  --fan-fill-middle: #C6D6CE;
  --fan-fill-base: #B5C8BF;
}

.fan-button:active .fan-drawing {
  transform: scale(0.992);
}

.fan-button:active .fan-highlight,
.fan-button:active .fan-hub-highlight {
  opacity: 0.12;
}

.fan-button:active .fan-pressed-shadow {
  opacity: 0.12;
}

.fan-button:focus-visible {
  outline: none;
}

.fan-button:focus-visible .fan-hub {
  stroke: #0A638F;
}

@media (prefers-reduced-motion: reduce) {
  .fan-fill-light,
  .fan-fill-middle,
  .fan-fill-base,
  .fan-highlight,
  .fan-hub-highlight,
  .fan-pressed-shadow {
    transition: none;
  }
}

