"use strict";

(function () {
  /*
   * Widget visual sin texto ni variables del PLC.
   *
   * El SVG conserva su relación de aspecto y queda
   * centrado al modificar el tamaño del widget.
   *
   * Una pala permanece orientada hacia arriba.
   * Las otras dos quedan distribuidas simétricamente.
   *
   * Hover y pulsación se gestionan mediante CSS.
   * No se configura ninguna acción de control al hacer clic.
   */
  window.onWidgetUpdate = function () {
    // No requiere procesar datos.
  };
})();
